import assert from "node:assert/strict";
import {createRequire} from "node:module";
import {existsSync,readFileSync,readdirSync} from "node:fs";
import ts from "typescript";

const require=createRequire(import.meta.url);
function loadStandaloneTypeScript(path){const source=readFileSync(path,"utf8"),compiled=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS}}).outputText,module={exports:{}};new Function("require","module","exports",compiled)(require,module,module.exports);return module.exports;}
function sourceFiles(directory){return readdirSync(directory,{withFileTypes:true}).flatMap(entry=>entry.isDirectory()?sourceFiles(`${directory}/${entry.name}`):entry.name.endsWith(".tsx")?[`${directory}/${entry.name}`]:[]);}
let passed=0;
function check(name,run){run();passed++;process.stdout.write(`✓ ${name}\n`);}

const {normalizeWebsiteUrl}=loadStandaloneTypeScript("lib/web-doctor/url-validation.ts");
const {isBlockedAddress}=loadStandaloneTypeScript("lib/web-doctor/dns-validation.ts");
const {parseHtml}=loadStandaloneTypeScript("lib/web-doctor/html-parser.ts");

check("URL normalization prefers HTTPS and removes fragments",()=>{assert.equal(normalizeWebsiteUrl("example.com/path#part").toString(),"https://example.com/path");assert.equal(normalizeWebsiteUrl("http://example.com").protocol,"http:");});
check("unsupported protocols, credentials and unusual ports are rejected",()=>{for(const value of ["file:///etc/passwd","ftp://example.com","https://user:pass@example.com","https://example.com:8443"]){assert.throws(()=>normalizeWebsiteUrl(value));}});
check("private, loopback, metadata, reserved and multicast addresses are blocked",()=>{for(const address of ["0.0.0.0","10.0.0.1","127.0.0.1","169.254.169.254","172.16.0.1","192.168.1.1","224.0.0.1","::1","fc00::1","fe80::1","ff00::1","2001:db8::1"]){assert.equal(isBlockedAddress(address),true,address);}assert.equal(isBlockedAddress("8.8.8.8"),false);});
check("HTML is parsed once into bounded diagnostic primitives",()=>{const document=parseHtml('<!doctype html><html lang="en"><head><title>Fixture title</title><meta name="robots" content="noindex"><meta name="description" content="Fixture description"></head><body><main><h1>Primary heading</h1><h2>Section</h2></main></body></html>');assert.equal(document.title,"Fixture title");assert.equal(document.robotsMeta,"noindex");assert.deepEqual(document.headings.map(item=>item.level),[1,2]);});
check("robots policy allows public content and excludes only the API",()=>{const robots=readFileSync("app/robots.ts","utf8");assert.equal(existsSync("public/robots.txt"),false);assert.match(robots,/userAgent:\s*"\*"/);assert.match(robots,/allow:\s*"\/"/);assert.match(robots,/disallow:\s*"\/api\/"/);assert.match(robots,/sitemap:\s*`\$\{SITE_URL\}\/sitemap\.xml`/);for(const publicPath of ["/_next/","/images/","/lab/","/work/","/guides/",".css",".js"])assert.equal(robots.includes(`disallow: "${publicPath}"`),false,publicPath);assert.doesNotMatch(robots,/noindex/i);});
check("production metadata origin comes from one validated HTTPS environment value",()=>{const env=readFileSync(".env.example","utf8"),config=readFileSync("lib/site-config.ts","utf8"),layout=readFileSync("app/layout.tsx","utf8"),sitemap=readFileSync("app/sitemap.ts","utf8"),robots=readFileSync("app/robots.ts","utf8"),structuredData=readFileSync("lib/seo/structured-data.ts","utf8"),nextConfig=readFileSync("next.config.ts","utf8");assert.match(env,/NEXT_PUBLIC_SITE_URL=https:\/\//);assert.match(config,/process\.env\.NEXT_PUBLIC_SITE_URL/);assert.match(config,/protocol!=="https:"/);assert.match(layout,/metadataBase:\s*new URL\(siteUrl\)/);assert.match(sitemap,/absoluteCanonicalUrl/);assert.match(robots,/SITE_URL/);assert.match(structuredData,/absoluteCanonicalUrl/);assert.match(nextConfig,/SITE_URL/);assert.doesNotMatch([layout,sitemap,robots,structuredData,nextConfig].join("\n"),/https:\/\/localhost|http:\/\/poojanchapagain/i);});
