check("dynamic sitemap covers public collections without state, redirects or employer case studies",()=>{const sitemap=readFileSync("app/sitemap.ts","utf8"),routes=loadStandaloneTypeScript("lib/seo/route-policy.ts");for(const collection of ["INDEXABLE_STATIC_ROUTES","labTools","webGuides","articles"])assert.match(sitemap,new RegExp(`\\.\\.\\.${collection}\\.map`));for(const prefix of ["/lab/","/guides/","/writing/"])assert.ok(sitemap.includes(prefix));assert.match(sitemap,/lastModified:new Date\(article\.date\)/);assert.equal((sitemap.match(/lastModified:/g)||[]).length,1);assert.doesNotMatch(sitemap,/new Date\(\)/);assert.doesNotMatch(sitemap,/\/api\/|seo-checker|searchParams|analysis-results|projects\.map|\/work\/\$\{/);assert.match(sitemap,/duplicate canonical URLs/);assert.ok(routes.INDEXABLE_STATIC_ROUTES.includes("/about"));assert.ok(routes.INDEXABLE_STATIC_ROUTES.includes("/work"));assert.ok(routes.INDEXABLE_STATIC_ROUTES.includes("/lab"));});
