check("public SEO avoids myths, doorway patterns and hidden keyword content",()=>{const roots=["app","components","data","lib"],files=roots.flatMap(root=>readdirSync(root,{recursive:true,withFileTypes:true}).filter(entry=>entry.isFile()&&/\.(?:ts|tsx|css)$/.test(entry.name)).map(entry=>`${entry.parentPath.replaceAll("\\","/")}/${entry.name}`)),sources=files.map(file=>({file,source:readFileSync(file,"utf8")})),combined=sources.map(item=>item.source).join("\n");assert.doesNotMatch(combined,/<meta\b[^>]*name=["']keywords["']|\bkeywords\s*:/i);assert.doesNotMatch(combined,/text-indent\s*:\s*-\d{3,}|font-size\s*:\s*0(?:px|rem|em)?/i);assert.doesNotMatch(combined,/\[(?:city|location|region|county|country)\]/i);assert.doesNotMatch(combined,/doorway\s+(?:page|route)|generate\s+hundreds|minimum\s+word\s+count|at least\s+\d{3,}\s+words/i);for(const {file,source} of sources){const locationMentions=source.match(/Glasgow|Scotland|Paisley|Kathmandu/gi)?.length??0;assert.ok(locationMentions<=8,`${file} repeats geographic terms ${locationMentions} times`);}const {projects}=loadStandaloneTypeScript("data/projects.ts"),{labTools}=loadStandaloneTypeScript("data/lab-tools.ts"),{webGuides}=loadStandaloneTypeScript("data/web-guides.ts"),{articles}=loadStandaloneTypeScript("data/writing.ts");for(const [label,items] of Object.entries({projects,labTools,webGuides,articles})){assert.ok(items.length>0&&items.length<50,`${label} must remain a deliberately bounded editorial collection`);assert.equal(new Set(items.map(item=>item.slug)).size,items.length,`${label} slugs must be unique`);}});
