check("contact accepts links in text but no version-one attachments",()=>{const component=readFileSync("components/contact/contact-chat.tsx","utf8"),validation=readFileSync("lib/contact/validation.ts","utf8"),route=readFileSync("app/api/contact/route.ts","utf8"),tests=readFileSync("tests/contact-validation.test.mjs","utf8"),docs=readFileSync("docs/contact-production-protection.md","utf8");assert.match(component,/No attachments\. Include a public link in your message/);assert.doesNotMatch(component,/<input[^>]*type="file"|accept=|multiple=|multipart\/form-data/i);assert.doesNotMatch(validation,/"attachment"|"attachments"|"file"|"fileUrl"/);assert.match(route,/application\/json/);assert.doesNotMatch(route,/formData\(\)|multipart|Blob|File/);for(const field of ["attachment","attachments","file","fileUrl"])assert.ok(tests.includes(`"${field}"`),field);assert.match(docs,/does not accept file uploads, multipart bodies/);});
check("contact treats submitted links as plain text without fetching previews",()=>{const contactFiles=["app/api/contact/route.ts","lib/contact/validation.ts","lib/contact/resend.ts"],source=contactFiles.map(file=>readFileSync(file,"utf8")).join("\n"),mock=readFileSync("tests/contact-resend.mock.mjs","utf8"),docs=readFileSync("docs/contact-production-protection.md","utf8");assert.doesNotMatch(source,/fetch\(|axios|undici|dns\.|lookup\(|openGraph|linkPreview|unfurl|scrape/i);assert.match(mock,/https:\/\/untrusted\.example\.test\/private-path\?token=visitor-text/);assert.match(mock,/html\.includes\("<a"\),false/);assert.match(docs,/does not request them, resolve DNS for them, follow redirects/);});
check("Turnstile uses managed client rendering and mandatory server verification when enabled",()=>{const widget=readFileSync("components/contact/turnstile-widget.tsx","utf8"),route=readFileSync("app/api/contact/route.ts","utf8"),server=readFileSync("lib/contact/turnstile.ts","utf8"),env=readFileSync(".env.example","utf8");assert.match(widget,/challenges\.cloudflare\.com\/turnstile\/v0\/api\.js\?render=explicit/);assert.match(widget,/appearance:"interaction-only"/);assert.match(widget,/action:"contact"/);assert.match(widget,/expired-callback/);assert.match(server,/challenges\.cloudflare\.com\/turnstile\/v0\/siteverify/);for(const field of ["secret","response","remoteip","idempotency_key"])assert.ok(server.includes(field),field);assert.match(server,/result\.action!==TURNSTILE_ACTION/);assert.match(server,/AbortSignal\.timeout\(VERIFY_TIMEOUT_MS\)/);assert.match(server,/process\.env\.NODE_ENV==="development"&&enabled\(process\.env\.TURNSTILE_DEV_BYPASS\)/);assert.ok(route.indexOf("verifyTurnstileToken")<route.indexOf("sendContactEmail(contact)"));for(const variable of ["NEXT_PUBLIC_TURNSTILE_SITE_KEY=","TURNSTILE_SECRET_KEY=","TURNSTILE_REQUIRED=","TURNSTILE_DEV_BYPASS="])assert.ok(env.includes(variable),variable);});
check("CSP grants only Turnstile's required browser origins when the widget is enabled",()=>{const config=readFileSync("next.config.ts","utf8");assert.match(config,/turnstileEnabled=Boolean\(process\.env\.NEXT_PUBLIC_TURNSTILE_SITE_KEY/);assert.match(config,/script-src[\s\S]*turnstileOrigin/);assert.match(config,/frame-src 'self'[\s\S]*turnstileOrigin/);assert.match(config,/turnstileOrigin="https:\/\/challenges\.cloudflare\.com"/);assert.doesNotMatch(config,/script-src[^\n]*\*/);assert.doesNotMatch(config,/frame-src[^\n]*\*/);assert.doesNotMatch(config,/resend\.com|api\.resend/);assert.match(config,/isDevelopment\?" 'unsafe-eval'":""/);});
check("contact rate limiting is honestly scoped as local best-effort protection",()=>{const limiter=readFileSync("lib/contact/rate-limit.ts","utf8"),docs=readFileSync("docs/contact-production-protection.md","utf8"),privacy=readFileSync("app/privacy/page.tsx","utf8");assert.match(limiter,/bestEffortContactRateLimit/);assert.match(limiter,/not shared nor durable/);assert.match(docs,/not a production-grade distributed IP rate limiter/);assert.match(docs,/hosting platform, reverse proxy, or WAF rate limit/);assert.match(docs,/shared infrastructure/);assert.match(docs,/do not add a database solely for this contact form/i);assert.match(privacy,/best-effort abuse protection within one running application instance/);assert.doesNotMatch(docs,/current map is production-safe|durable in-memory/i);});
check("contact origin checks are additional signals and delivery fields are rejected",()=>{const route=readFileSync("app/api/contact/route.ts","utf8"),origin=readFileSync("lib/contact/request-origin.ts","utf8"),validation=readFileSync("lib/contact/validation.ts","utf8"),docs=readFileSync("docs/contact-production-protection.md","utf8");assert.match(route,/browserRequestOriginIsAllowed\(request\)/);assert.match(origin,/sec-fetch-site/);assert.match(origin,/fetchSite==="cross-site"/);assert.match(origin,/request\.headers\.get\("host"\)/);assert.match(origin,/host===parsedOrigin\.host/);assert.match(validation,/ACCEPTED_FIELDS=new Set/);assert.match(validation,/Object\.keys\(value\)\.some\(field=>!ACCEPTED_FIELDS\.has\(field\)\)/);for(const field of ["to","from","subject","cc","bcc","headers","template","destinationEmail"])assert.ok(!validation.match(/ACCEPTED_FIELDS=new Set\(([^;]+)/)?.[1].includes(`"${field}"`),field);assert.match(docs,/supplement rather than replace validation, Turnstile/);});
check("every contact response is non-cacheable and provider details stay private",()=>{const route=readFileSync("app/api/contact/route.ts","utf8"),diagnostics=readFileSync("lib/contact/diagnostics.ts","utf8"),docs=readFileSync("docs/contact-production-protection.md","utf8");assert.match(route,/"cache-control":"private, no-store, max-age=0"/);assert.match(route,/"pragma":"no-cache"/);assert.match(route,/"expires":"0"/);assert.match(route,/"vary":"Origin"/);assert.match(route,/headers:\{\.\.\.extra,\.\.\.responseHeaders\}/);assert.doesNotMatch(route,/error\.message|error\.stack|JSON\.stringify\(error\)|provider response/i);assert.doesNotMatch(diagnostics,/error\.message|error\.stack|email|message|api.?key/i);assert.match(docs,/credentials, stack traces and internal error messages are never returned/);});
check("contact API exposes a minimal stable response contract",()=>{const route=readFileSync("app/api/contact/route.ts","utf8"),resend=readFileSync("lib/contact/resend.ts","utf8");assert.match(route,/const failure=\(code:ContactErrorCode,message:string,status:number[\s\S]*\{ok:false,code,message\}/);assert.match(route,/failure\("VALIDATION_ERROR","Check your email and message\.",400\)/);assert.match(route,/failure\("SEND_FAILED","Message could not be sent right now\.",502\)/);assert.match(route,/await sendContactEmail\(contact\);return json\(\{ok:true\}\)/);assert.match(resend,/const \{error\}=await emailClient\.send/);assert.doesNotMatch(route,/return json\(\{ok:true,message:|messageId|message_id|providerMetadata|emailHeaders|CONTACT_TO_EMAIL/);assert.doesNotMatch(resend,/return\s+(?:data|response)|return\s+\{[^}]*id/);for(const leak of ["RESEND_API_KEY","TURNSTILE_SECRET_KEY","process.cwd","__dirname","error.stack","error.message"])assert.ok(!route.includes(leak),leak);});
check("contact client and server share strict TypeScript contracts",()=>{const files=["lib/contact/types.ts","lib/contact/validation.ts","lib/contact/resend.ts","app/api/contact/route.ts","components/contact/contact-chat.tsx"],sources=files.map(file=>readFileSync(file,"utf8")),types=sources[0],combined=sources.join("\n");for(const name of ["ContactRequest","ContactResponse","ContactTopic"])assert.match(types,new RegExp(`export type ${name}`));assert.match(sources[3],/ContactResponse/);assert.match(sources[4],/ContactRequest,ContactResponse,ContactTopic/);assert.doesNotMatch(combined,/\bany\b|@ts-ignore|eslint-disable/);});
check("search launch handoff lists every owner-only action without a fake token",()=>{const checklist=readFileSync("docs/search-engine-launch-checklist.md","utf8");assert.match(checklist,/## OWNER ACTION REQUIRED/);for(const task of ["Add the real production domain","Verify Google Search Console","Submit sitemap.xml","Inspect the homepage in URL Inspection","Inspect the Web Doctor page","Inspect the SVG Base64 Converter","Request indexing for the important pages","Monitor the Page Indexing report","Monitor Core Web Vitals","Monitor Search Performance queries and CTR"])assert.ok(checklist.includes(task),task);assert.match(checklist,/NEXT_PUBLIC_GOOGLE_SITE_VERIFICATION=\n/);assert.match(checklist,/intentionally blank in source control/);assert.doesNotMatch(checklist,/google-site-verification=[A-Za-z0-9_-]+|NEXT_PUBLIC_GOOGLE_SITE_VERIFICATION=\S+/);});

